import { validateNodes } from './validate-nodes.mjs';

function uniqueDeps(dependsOn) {
  if (!dependsOn || dependsOn.length === 0) return [];
  const seen = new Set();
  const out = [];
  for (const dep of dependsOn) {
    if (!seen.has(dep)) {
      seen.add(dep);
      out.push(dep);
    }
  }
  return out;
}

export function planBuild(nodes) {
  validateNodes(nodes);
  if (nodes.length === 0) return [];

  const indices = new Map(nodes.map((n, i) => [n.id, i]));
  const inDegree = new Map();
  const outgoing = new Map();

  for (const node of nodes) {
    inDegree.set(node.id, 0);
    outgoing.set(node.id, []);
  }

  for (const node of nodes) {
    for (const dep of uniqueDeps(node.dependsOn)) {
      inDegree.set(node.id, inDegree.get(node.id) + 1);
      outgoing.get(dep).push(node.id);
    }
  }

  const result = [];
  const scheduled = new Set();
  const degree = new Map(inDegree);

  while (result.length < nodes.length) {
    let pick = null;
    let pickIndex = Infinity;
    for (const node of nodes) {
      if (scheduled.has(node.id)) continue;
      if (degree.get(node.id) !== 0) continue;
      const idx = indices.get(node.id);
      if (idx < pickIndex) {
        pickIndex = idx;
        pick = node.id;
      }
    }
    if (pick === null) {
      throw new Error('cycle');
    }
    scheduled.add(pick);
    result.push(pick);
    for (const next of outgoing.get(pick)) {
      degree.set(next, degree.get(next) - 1);
    }
  }

  return result;
}

