function uniqueDeps(dependsOn) {
  if (!dependsOn || dependsOn.length === 0) return [];
  const seen = new Set();
  const out = [];
  for (const dep of dependsOn) {
    if (!seen.has(dep)) {
      seen.add(dep);
      out.push(dep);
    }
  }
  return out;
}

export function validateNodes(nodes) {
  if (!Array.isArray(nodes)) throw new TypeError('nodes must be an array');

  const seenIds = new Set();
  const allIds = new Set();

  for (const node of nodes) {
    if (node === null || typeof node !== 'object' || Array.isArray(node)) {
      throw new TypeError('node must be an object');
    }
    const { id, dependsOn } = node;
    if (typeof id !== 'string' || id.length === 0) {
      throw new TypeError('id must be a nonempty string');
    }
    if (seenIds.has(id)) {
      throw new Error('duplicate node id');
    }
    seenIds.add(id);
    allIds.add(id);

    if (dependsOn === undefined) continue;
    if (!Array.isArray(dependsOn)) {
      throw new TypeError('dependsOn must be an array');
    }
    for (const dep of dependsOn) {
      if (typeof dep !== 'string' || dep.length === 0) {
        throw new TypeError('dependency id must be a nonempty string');
      }
    }
  }

  for (const node of nodes) {
    const deps = node.dependsOn;
    if (!deps) continue;
    const counted = new Set();
    for (const dep of deps) {
      if (counted.has(dep)) continue;
      counted.add(dep);
      if (!allIds.has(dep)) {
        throw new Error('missing dependency');
      }
      if (dep === node.id) {
        throw new Error('cycle');
      }
    }
  }

  if (nodes.length === 0) return nodes;

  const indices = new Map(nodes.map((n, i) => [n.id, i]));
  const inDegree = new Map();
  const outgoing = new Map();
  for (const id of allIds) {
    inDegree.set(id, 0);
    outgoing.set(id, []);
  }
  for (const node of nodes) {
    for (const dep of uniqueDeps(node.dependsOn)) {
      inDegree.set(node.id, inDegree.get(node.id) + 1);
      outgoing.get(dep).push(node.id);
    }
  }

  const queue = [];
  for (const node of nodes) {
    if (inDegree.get(node.id) === 0) queue.push(node.id);
  }
  queue.sort((a, b) => indices.get(a) - indices.get(b));

  let processed = 0;
  while (queue.length > 0) {
    const id = queue.shift();
    processed++;
    for (const next of outgoing.get(id)) {
      const deg = inDegree.get(next) - 1;
      inDegree.set(next, deg);
      if (deg === 0) {
        queue.push(next);
        queue.sort((a, b) => indices.get(a) - indices.get(b));
      }
    }
  }
  if (processed !== allIds.size) {
    throw new Error('cycle detected');
  }

  return nodes;
}

